companies = list_companies({})
companies_by_domain = fold acc = {} for c in companies {
  return acc + { [c.domain]: c.name }
}

first = list_contacts({ page: 1 })
remaining = for page in list.range(2, first.total_pages + 1) {
  return list_contacts({ page: page }).items
}
all_contacts = fold acc = first.items for page_items in remaining {
  return acc + page_items
}

results = for contact in all_contacts {
  phone_fixed = false
  new_phone = null
  if contact.phone != null {
    p = contact.phone
    is_valid = regex.test(p, "^\\+1[0-9]{10}$")
    if not is_valid {
      digits = regex.replace(p, "[^0-9]", "")
      digits10 = if text.starts_with(digits, "1") and text.length(digits) == 11 {
        return text.slice(digits, 1)
      } else if text.length(digits) == 10 {
        return digits
      } else {
        return digits
      }
      if text.length(digits10) == 10 {
        new_phone = "+1" + digits10
        phone_fixed = true
      }
    }
  }

  company_filled = false
  new_company = null
  needs_company = contact.company == null or contact.company == ""
  if needs_company and contact.email != null {
    parts = text.split(contact.email, "@")
    if list.length(parts) >= 2 {
      domain = parts[list.length(parts) - 1]
      if domain in companies_by_domain {
        new_company = companies_by_domain[domain]
        company_filled = true
      }
    }
  }

  if phone_fixed or company_filled {
    _ = update_contact({
      id: contact.id,
      phone: new_phone if phone_fixed else null,
      company: new_company if company_filled else null
    })
  }

  return { phone_fixed: phone_fixed, company_filled: company_filled }
}

phones_fixed = fold acc = 0 for r in results {
  return acc + (1 if r.phone_fixed else 0)
}
companies_filled = fold acc = 0 for r in results {
  return acc + (1 if r.company_filled else 0)
}

submitted = submit_result({ answer: { phones_fixed: phones_fixed, companies_filled: companies_filled } })
return { phones_fixed: phones_fixed, companies_filled: companies_filled, submitted: submitted }

